import { useInsertionEffect } from 'react';

const stylesCache = new Set();

function useDynamicStyle(styleRule) {
  useInsertionEffect(() => {
    if (!stylesCache.has(styleRule)) {
      const styleTag = document.createElement('style');
      styleTag.textContent = styleRule;
      document.head.appendChild(styleTag);
      stylesCache.add(styleRule);
    }
  }, [styleRule]);
}

export default function StyledButton() {
  useDynamicStyle('.my-button { background: royalblue; color: white; padding: 10px; border-radius: 5px; }');

  return <button className="my-button">Click Me</button>;
}
